def solve(n: int) -> int:
    memo = {}
    def fib(k):
        if k <= 1: return k
        if k not in memo:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]
    return fib(n)

def solve(start: int, stop: int, step: int) -> list:
    def gen(a, b, c):
        curr = a
        while curr < b:
            yield curr
            curr += c
    return list(gen(start, stop, step))

def solve(a: int, b: int) -> str:
    try:
        return f"{a / b:.2f}"
    except ZeroDivisionError:
        return "Error: Division by zero"
